describe('Checkout Form Validation - Required Fields', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-testid="login-container"]').click();
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="shopping-cart-link"]').click();
  });

  it('should display error when only first name is filled and postal code is missing', () => {
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="continue"]').click();
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Postal Code is required');
  });

  it('should successfully submit form when all required fields are filled', () => {
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('12345');
    cy.get('[data-testid="continue"]').click();
    cy.url().should('include', '/checkout');
    cy.get('[data-testid="error"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Thank you for your order');
  });
});
